import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        // Input validation for dates
        if (startDate == null || !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate == null || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Whitelist report types
        if (!"sales".equals(reportType) && !"inventory".equals(reportType)
                && !"hr".equals(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - department filter uses parameterized portion
        // but sort column is dynamic for flexibility
        String baseQuery = "SELECT id, name, amount, created_at, department "
                + "FROM reports WHERE report_type = ? "
                + "AND created_at BETWEEN ? AND ? ";

        if (department != null && !department.isEmpty()) {
            baseQuery += "AND department = ? ";
        }

        // Sort column - we validate against allowed columns
        String[] allowedCols = {"id", "name", "amount", "created_at", "department"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedCols) {
                if (col.equals(sortCol)) {
                    validSort = true;
                    break;
                }
            }
        }

        // Sort direction - VULNERABILITY: not properly validated
        // Developer assumed only 'ASC' or 'DESC' would be sent
        if (sortDir == null) sortDir = "ASC";

        if (validSort) {
            baseQuery += "ORDER BY " + sortCol + " " + sortDir;
        } else {
            baseQuery += "ORDER BY created_at ASC";
        }

        log.info("Executing report query for type=" + reportType + ", dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, reportType);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            if (department != null && !department.isEmpty()) {
                stmt.setString(4, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"amount\":%.2f,\"dept\":\"%s\"}",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getDouble("amount"), rs.getString("department"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }
}
